INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('steinbeck/nmrxiv-downloader/nmrxiv', 'community', 'steinbeck', 'nmrxiv-downloader', 'steinbeck/nmrxiv-downloader', 'nmrxiv', 0, 0, 50, '2026-02-24T11:52:28.983Z', '2026-02-24T11:55:21.278Z', 'e8c886a39062e7ec9d8fc26d902682e5528c88f8e0720b531a9dca881d06a1f9', '{"id":"steinbeck/nmrxiv-downloader/nmrxiv","name":"nmrxiv","description":{"zh":"nmrxiv下载器是一个Python CLI工具，用于在nmrxiv.org上搜索和下载NMR光谱数据集","ja":"nmrxivダウンローダーはnmrxiv.org上的NMRスペクトルデータセットを検索してダウンロードするためのPython CLIツール","ko":"nmrxiv 다운로드기는 nmrxiv.org上的 NMR 분광 데이터셋을 검색 및 다운로드하기 위한 Python CLI 도구","es":"nmrxiv es una herramienta de línea de comandos de Python para buscar y descargar conjuntos de datos NMR de nmrxiv.org. Ofrece funcionalidades para listar proyectos y conjuntos de datos, buscar moléculas y más","fr":"nmrxiv est un outil de ligne de commande Python pour rechercher et télécharger des jeux de données NMR à partir de nmrxiv.org. Il propose des fonctionnalités pour lister les projets et les jeux de données, rechercher des molécules et plus encore","de":"nmrxiv ist ein Python-CLI-Tool zum Suchen und Herunterladen von NMR-Datensätzen von nmrxiv.org. Es bietet Funktionen zum Auflisten von Projekten und Datensätzen, zur Suche nach Molekülen und mehr","pt":"A ferramenta nmrxiv é uma CLI Python para busca e download de conjuntos de dados de NMR de nmrxiv.org. Ela permite listar projetos e conjuntos de dados, buscar moléculas e mais.","ru":"Инструмент nmrxiv - это CLI на Python для поиска и скачивания наборов данных ЯМР с nmrxiv.org. Он позволяет листать проекты и наборы данных, искать молекулы и многое другое.","ar":"أداة nmrxiv هي سطر أوامر بايثون للبحث وتنزيل مجموعات بيانات الرنين المغناطيسي النووي من nmrxiv.org. يمكنها قائمة المشاريع ومجموعات البيانات، البحث عن الجزيئات والمزيد","en":"Python CLI for Claude Code to search and download NMR datasets from nmrxiv.org"},"seo":{"title":{"zh":"nmrxiv下载器：NMR数据集搜索和下载工具","ja":"nmrxivダウンローダー：NMRデータセット検索とダウンロードツール","ko":"nmrxiv 다운로드기: NMR 데이터셋 검색 및 다운로드 도구","es":"nmrxiv: Herramienta CLI para búsqueda y descarga de conju...","fr":"nmrxiv: Outil CLI pour la recherche et le téléchargement ...","de":"nmrxiv: CLI-Tool für die Suche und den Download von NMR-D...","pt":"nmrxiv: Ferramenta CLI para Buscar e Baixar Conjuntos de ...","ru":"nmrxiv: CLI инструмент для поиска и скачивания наборов да...","ar":"nmrxiv: أداة سطر الأوامر للبحث وتنزيل مجموعات بيانات الرن...","en":"nmrxiv"},"description":{"zh":"nmrxiv下载器是一个Python CLI工具，用于在nmrxiv.org上搜索和下载NMR光谱数据集","ja":"nmrxivダウンローダーはnmrxiv.org上的NMRスペクトルデータセットを検索してダウンロードするためのPython CLIツール","ko":"nmrxiv 다운로드기는 nmrxiv.org上的 NMR 분광 데이터셋을 검색 및 다운로드하기 위한 Python CLI 도구","es":"nmrxiv es una herramienta de línea de comandos de Python para buscar y descargar conjuntos de datos NMR de nmrxiv.org. Ofrece funcionalidades para listar pro...","fr":"nmrxiv est un outil de ligne de commande Python pour rechercher et télécharger des jeux de données NMR à partir de nmrxiv.org. Il propose des fonctionnalités...","de":"nmrxiv ist ein Python-CLI-Tool zum Suchen und Herunterladen von NMR-Datensätzen von nmrxiv.org. Es bietet Funktionen zum Auflisten von Projekten und Datensät...","pt":"A ferramenta nmrxiv é uma CLI Python para busca e download de conjuntos de dados de NMR de nmrxiv.org. Ela permite listar projetos e conjuntos de dados, busc...","ru":"Инструмент nmrxiv - это CLI на Python для поиска и скачивания наборов данных ЯМР с nmrxiv.org. Он позволяет листать проекты и наборы данных, искать молекулы ...","ar":"أداة nmrxiv هي سطر أوامر بايثون للبحث وتنزيل مجموعات بيانات الرنين المغناطيسي النووي من nmrxiv.org. يمكنها قائمة المشاريع ومجموعات البيانات، البحث عن الجزيئا...","en":"Python CLI for Claude Code to search and download NMR datasets from nmrxiv.org"},"definition":{"en":"Python CLI for Claude Code to search and download NMR datasets from nmrxiv.org"},"features":