INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Peiiii/skild/skild', 'community', 'Peiiii', 'skild', 'Peiiii/skild', 'skild', 0, 0, 75, '2026-02-20T04:13:19.578Z', '2026-02-20T04:54:24.725Z', '1a646f1a3ea62ad7724b4cf478e9ceb91c10bb91973002c887f43ab4c7111e3f', '{"id":"Peiiii/skild/skild","name":"skild","description":{"zh":"skild AI skild npm AI","ja":"skildAI npm AI","ko":"skild AI skild npm AI","es":"skild es el gestor de paquetes para habilidades de agentes de IA, que permite instalar, gestionar y publicar habilidades de manera sencilla","fr":"skild est le gestionnaire de packages pour les compétences d''agents IA, qui permet d''installer, de gérer et de publier des compétences de manière simple","de":"skild ist der Paket-Manager für KI-Agenten-Fähigkeiten, der das Installieren, Verwalten und Veröffentlichen von Fähigkeiten auf einfache Weise ermöglicht","pt":"O skild é um gerenciador de habilidades de agentes de IA que permite instalar, gerenciar e publicar habilidades com facilidade","ru":"Skild - менеджер навыков агентов ИИ, который позволяет устанавливать, управлять и публиковать навыки с легкостью","ar":"skild هو مدير مهارات وكلاء الذكاء الاصطناعي الذي يسمح بتثبيت وإدارة ونشر المهارات بسهولة","en":"The npm for Agent Skills — Discover, install, manage, and publish AI Agent Skills with ease"},"seo":{"title":{"zh":"skild AI ","ja":"skildAI","ko":"skild AI ","es":"skild: Gestor de habilidades de agentes de IA","fr":"skild: Gestionnaire de compétences d''agents IA","de":"skild: Manager für KI-Agenten-Fähigkeiten","pt":"skild: Gerenciador de Habilidades de Agentes de IA","ru":"skild: Менеджер навыков агентов ИИ","ar":"skild: مدير مهارات وكلاء الذكاء الاصطناعي","en":"skild"},"description":{"zh":"skild AI skild npm AI","ja":"skildAI npm AI","ko":"skild AI skild npm AI","es":"skild es el gestor de paquetes para habilidades de agentes de IA, que permite instalar, gestionar y publicar habilidades de manera sencilla","fr":"skild est le gestionnaire de packages pour les compétences d''agents IA, qui permet d''installer, de gérer et de publier des compétences de manière simple","de":"skild ist der Paket-Manager für KI-Agenten-Fähigkeiten, der das Installieren, Verwalten und Veröffentlichen von Fähigkeiten auf einfache Weise ermöglicht","pt":"O skild é um gerenciador de habilidades de agentes de IA que permite instalar, gerenciar e publicar habilidades com facilidade","ru":"Skild - менеджер навыков агентов ИИ, который позволяет устанавливать, управлять и публиковать навыки с легкостью","ar":"skild هو مدير مهارات وكلاء الذكاء الاصطناعي الذي يسمح بتثبيت وإدارة ونشر المهارات بسهولة","en":"The npm for Agent Skills — Discover, install, manage, and publish AI Agent Skills with ease"},"definition":{"en":"The npm for Agent Skills — Discover, install, manage, and publish AI Agent Skills with ease"},"features":{"zh":["AI","npm","AI","API","AI","AI"],"ja":["AI","npm","AI","API","AI","AI"],"ko":["AI","npm","AI","API","AI","AI"],"es":["Instalación de habilidades de agentes de IA","Gestión de habilidades instaladas","Publicación de habilidades para compartir con la comunidad","Búsqueda y descubrimiento de nuevas habilidades","Registro y catalogación automática de habilidades"],"fr":["Installation de compétences d''agents IA","Gestion de compétences installées","Publication de compétences pour les partager avec la communauté","Recherche et découverte de nouvelles compétences","Enregistrement et catalogage automatique de compétences"],"de":["Installation von KI-Agenten-Fähigkeiten","Verwaltung von installierten Fähigkeiten","Veröffentlichung von Fähigkeiten zur gemeinsamen Nutzung","Suche und Entdeckung neuer Fähigkeiten","Registrierung und automatische Katalogisierung von Fähigkeiten"],"pt":["Instalação de novas habilidades para agentes de IA","Gerenciamento de habilidades instaladas","Publicação de habilidades para compartilhar com a comunidade","Pesquisa e descoberta de novas habilidades","Índice de habilidades para agentes de IA"],"ru":["Установка новых навыков для агентов ИИ","Управление установленными навыками","Публикация навыков для обмена с сообществом","Поиск и открытие новых навыков","Индекс навыков для агентов ИИ"],"ar":["تثبيت مهارات جديدة ل와كلاء الذكاء الاصطناعي","إدارة المهارات المثبتة","نشر المهارات لمشاركتها مع المجتمع","بحث واكتشاف مهارات جديدة","فهرس المهارات لواكلاء الذكاء الاصطناعي"]},"keywords":{"zh":["AI","skild","npm","AI","AI","API","AI","AI"],"ja":["AI","skild","npm","AI","AI","API","AI","AI"],"ko":["AI","skild","npm","AI","AI","API","AI","AI"],"es":["skild","agentes de IA","habilidades de agentes de IA","gestor de paquetes","instalación de habilidades","gestión de habilidades","publicación de habilidades","búsqueda de habilidades","desarrollo de IA"],"fr":["skild","agents IA","compétences d''agents IA","gestionnaire de packages","installation de compétences","gestion de compétences","publication de compétences","recherche de compétences","développement IA"],"de":["skild","KI-Agents","KI-Agenten-Fähigkeiten","Paket-Manager","Installation von Fähigkeiten","Verwaltung von Fähigkeiten","Veröffentlichung von Fähigkeiten","Suche nach Fähigkeiten","KI-Entwicklung"],"pt":["skild","habilidades de agentes de IA","gerenciador de pacotes","instalação de habilidades","gerenciamento de habilidades","publicação de habilidades","pesquisa de habilidades","índice de habilidades"],"ru":["skild","навыки агентов ИИ","менеджер пакетов","установка навыков","управление навыками","публикация навыков","поиск навыков","индекс навыков"],"ar":["skild","مهارات وكلاء الذكاء الاصطناعي","مدير حزم","تثبيت مهارات","إدارة المهارات","نشر المهارات","بحث المهارات","فهرس المهارات"]}},"owner":"Peiiii","repo":"skild","repoPath":"Peiiii/skild","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"skild","description":"Skill package manager for AI Agents — install, manage, and publish Agent Skills.","version":"0.2.10","tags":"","bodyPreview":"# skild\n\n**skild** is the package manager for Agent Skills — like npm, but for AI agents.\n\n## When to Use\n\nUse this skill when:\n- Installing new capabilities for AI agents\n- Managing installed Skills (list, update, uninstall)\n- Publishing Skills to share with the community\n- Searching or discovering new Skills\n\n## Agent Search & Discovery (Skild Index)\n\nWhen an agent needs to find Skills from the Skild index (registry + linked + auto catalog), use the Registry API:\n\n```bash\n# Unified discovery (","body":"# skild\n\n**skild** is the package manager for Agent Skills — like npm, but for AI agents.\n\n## When to Use\n\nUse this skill when:\n- Installing new capabilities for AI agents\n- Managing installed Skills (list, update, uninstall)\n- Publishing Skills to share with the community\n- Searching or discovering new Skills\n\n## Agent Search & Discovery (Skild Index)\n\nWhen an agent needs to find Skills from the Skild index (registry + linked + auto catalog), use the Registry API:\n\n```bash\n# Unified discovery (registry + linked skills)\ncurl \"https://registry.skild.sh/discover?q=<query>&limit=20\"\n\n# Resolve a short alias (optional)\ncurl \"https://registry.skild.sh/resolve?alias=<alias>\"\n```\n\n**Notes:**\n- Prefer `alias` if present; it provides the shortest install command.\n- Use the returned `install` string directly (quotes may appear when a `#ref` is required).\n- `/discover` supports pagination and filtering:\n  - `cursor=<nextCursor>` for pagination\n  - `sort=updated|new|downloads_7d|downloads_30d|stars|stars_30d`\n  - `skillset=true|false` and `category=<id>` to narrow results\n- If you need to browse linked items only:\n  - `https://registry.skild.sh/linked-items?limit=20`\n- CLI `skild search` uses the same unified index.\n\n## Agent Workflow (Recommended)\n\n1) Search via `/discover` and shortlist results by description/tags.  \n2) Confirm with the user and pick the best match.  \n3) Install using the provided `install` command (or alias).  \n4) Manage using `skild list / info / update / uninstall / sync`.\n\n## Prerequisites\n\nNode.js ≥18 is required.\n\n```bash\nnpm install -g skild\n```\n\n## Core Commands\n\n### Install a Skill\n\n```bash\n# From GitHub (shorthand)\nskild install owner/repo/path/to/skill\n\n# From registry\nskild install @publisher/skill-name\n\n# From local directory\nskild install ./my-skill\n\n# Aliases (npm-style)\nskild add @publisher/skill-name\nskild i @publisher/skill-name\n\n# Pick one Skill when source has multiple SKILL.md\nskild install owner/repo --skill skills/pdf\n```\n\n### List Installed Skills\n\n```bash\nskild list\n```\n\nOutput groups Skills by type: Skillsets, Skills, Dependencies.\n\n### Manage Skills\n\n```bash\nskild info <skill>       # Show details\nskild update <skill>     # Update to latest\nskild uninstall <skill>  # Remove\nskild validate <path>    # Validate structure\nskild sync [skills...]   # Sync across platforms\n```\n\n### Search Registry\n\n```bash\nskild search <query>\n```\n\nBrowse online: [hub.skild.sh](https://hub.skild.sh)\n\n## Target Platforms\n\n| Platform | Option | Global Path | Project Path |\n|----------|--------|-------------|--------------|\n| Claude | `-t claude` (default) | `~/.claude/skills` | `./.claude/skills` |\n| Codex | `-t codex` | `~/.codex/skills` | `./.codex/skills` |\n| Copilot | `-t copilot` | `~/.github/skills` | `./.github/skills` |\n| Antigravity | `-t antigravity` | `~/.gemini/antigravity/skills` | `./.agent/skills` |\n| OpenCode | `-t opencode` | `~/.config/opencode/skill` | `./.opencode/skill` |\n| Cursor | `-t cursor` | `~/.cursor/skills` | `./.cursor/skills` |\n| Windsurf | `-t windsurf` | `~/.windsurf/skills` | `./.windsurf/skills` |\n| Agents | `-t agents` | `~/.agents/skills` | `./.agents/skills` |\n\n```bash\n# Example: Install to Antigravity\nskild install @publisher/skill -t antigravity\n\n# Project-level installation\nskild install @publisher/skill --local\n```\n\n## Defaults & Scope\n\n```bash\n# Default platform & scope\nskild config set defaultPlatform codex\nskild config set defaultScope project\n\n# Default repo for push\nskild config set push.defaultRepo owner/repo\n```\n\n## Skillsets\n\nSkillsets bundle multiple Skills for one-command installation:\n\n```bash\nskild install @skild/data-analyst-pack\n# Installs: csv, pandas, sql-helper...\n```\n\n## Publishing Skills\n\n```bash\n# 1. Create account\nskild signup\n\n# 2. Login\nskild login\n\n# 3. Publish\nskild publish --dir ./my-skill\n```\n\n## Push to Git Repos (Registry-free)\n\nUse `skild push` to sync a Skill into a Git repository and push changes.\n\n```bash\n# Push to GitHub by owner/repo\nskild push owner/repo --dir ./my-skill\n\n# Set a default repo (omit <repo> afterwards)\nskild config set push.defaultRepo owner/repo\nskild push --dir ./my-skill\n\n# Push to a local repo path\nskild push ~/work/skills-repo --local --dir ./my-skill\n\n# Push to a specific subdirectory\nskild push owner/repo --dir ./my-skill --path skills/my-skill\n\n# Push to a branch (or append #branch to the repo)\nskild push owner/repo#dev --dir ./my-skill\n```\n\n**Notes:**\n- The target path defaults to `skills/<skill-name>` derived from `SKILL.md`.\n- Target path cannot be the repo root.\n- The command clones, commits, and pushes to the remote branch.\n- For `owner/repo`, skild tries SSH first and falls back to HTTPS if SSH auth fails.\n- `skild push <repo>` always overrides the default repo.\n- You can also set `SKILD_DEFAULT_PUSH_REPO` to override the default repo per shell.\n\n## Command Reference\n\nFor the complete command reference with all options, see [commands.md](./commands.md).\n\n## Skillsets\n\nFor detailed Skillsets guide (bundles of Skills), see [skillsets.md](./skillsets.md).\n\n## Troubleshooting\n\nFor common issues and solutions, see [troubleshooting.md](./troubleshooting.md).\n\n## More Info\n\n- Website: [skild.sh](https://skild.sh)\n- Hub: [hub.skild.sh](https://hub.skild.sh)\n- Documentation: [GitHub](https://github.com/Peiiii/skild/tree/main/docs)\n"},"lastSynced":"2026-02-20T04:54:24.725Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing streamlined skill management and discovery capabilities.","zh":"非常适合需要简化技能管理和发现能力的AI代理开发人员。","ja":"AIエージェント開発者がストリームライン化されたスキル管理と発見の機能を必要とする場合に最適です。","ko":"스트림 라인화된 스킬 관리 및 발견 기능이 필요한 AI 에이전트 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de agentes de IA que necesitan una gestión y capacidad de descubrimiento de habilidades optimizadas.","fr":"Parfait pour les développeurs d''agents d''IA ayant besoin d''une gestion et de capacités de découverte de compétences rationalisées.","de":"Perfekt für AI-Agent-Entwickler, die eine optimierte Fähigkeitsverwaltung und Entdeckungsfunktionen benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que necessitam de gestão e capacidades de descoberta de habilidades simplificadas.","ru":"Идеально для разработчиков агентов ИИ, которым необходима упрощенная система управления навыками и возможностями их обнаружения.","ar":"مثالي لمنطقي 개발 وكلاء الاستخبارات الاصطناعية الذين يحتاجون إلى إدارة مهارات واكتشاف مميزات مبسطة."},"recommendation":{"en":"Empowers agents to seamlessly install, manage, and publish skills using the Skild registry and API, facilitating efficient discovery and integration of new capabilities through the Skild Index.","zh":"赋予代理无缝安装、管理和发布技能的能力，使用Skild注册表和API，通过Skild索引实现新的功能的高效发现和集成。","ja":"SkildレジストリとAPIを使用して、エージェントにスキルをシームレスにインストール、管理、および公開する機能を提供し、Skildインデックスを介して新しい機能の効率的な発見と統合を促進します。","ko":"Skild 등록표와 API를 사용하여 에이전트가 스킬을無縫的に 설치, 관리 및 발행 할 수 있는 능력을 부여하여, Skild 색인을 통해 새로운 기능의 효율적인 발견 및 통합을 촉진합니다.","es":"Habilita a los agentes a instalar, gestionar y publicar habilidades de forma fluida mediante el registro y la API de Skild, facilitando el descubrimiento y la integración eficientes de nuevas capacidades a través del índice de Skild.","fr":"Permet aux agents d''installer, de gérer et de publier des compétences de manière fluide en utilisant le registre et l''API Skild, facilitant ainsi la découverte et l''intégration efficientes de nouvelles capacités via l''Index Skild.","de":"Ermöglicht es den Agenten, Fähigkeiten nahtlos über das Skild-Register und die Skild-API zu installieren, zu verwalten und zu veröffentlichen, wodurch eine effiziente Entdeckung und Integration neuer Fähigkeiten über den Skild-Index ermöglicht wird.","pt":"Habilita os agentes a instalar, gerenciar e publicar habilidades de forma transparente, utilizando o registro e a API da Skild, facilitando a descoberta e integração eficientes de novas capacidades através do Índice da Skild.","ru":"Наделяет агентов возможностью без проблем устанавливать, управлять и публиковать навыки, используя реестр и API Skild, облегчая эффективное обнаружение и интеграцию новых возможностей через Индекс Skild.","ar":"يمنح وكلاء القدرة على تثبيت وإدارة ونشر المهارات بسهولة، باستخدام سجل و API Skild، و تسهيل اكتشاف دمج الكفاءات الجديدة بفعالية من خلال فهرس Skild."},"useCases":{"en":["Discovering and installing new skills from the Skild Index","Managing and updating existing skills for optimal performance","Publishing custom skills to share with the AI agent community"],"zh":["从Skild索引中发现和安装新的技能","管理和更新现有技能以实现最佳性能","发布自定义技能与AI代理社区共享"],"ja":["Skildインデックスから新しいスキルを発見してインストールする","既存のスキルを管理して更新して最適な性能を実現する","カスタムスキルを公開してAIエージェントコミュニティと共有する"],"ko":["Skild 색인에서 새로운 스킬을 발견하고 설치하기","기존 스킬을 관리하고 업데이트 하여 최적의 성능을 달성하기","사용자 정의 스킬을 발행하여 AI 에이전트 커뮤니티와 공유하기"],"es":["Descubrir e instalar nuevas habilidades desde el índice de Skild","Gestionar y actualizar habilidades existentes para un rendimiento óptimo","Publicar habilidades personalizadas para compartir con la comunidad de agentes de IA"],"fr":["Découvrir et installer de nouvelles compétences à partir de l''Index Skild","Gérer et mettre à jour des compétences existantes pour une performance optimale","Publier des compétences personnalisées pour les partager avec la communauté d''agents d''IA"],"de":["Entdecken und Installieren neuer Fähigkeiten aus dem Skild-Index","Verwalten und aktualisieren bestehender Fähigkeiten für ein optimales Leistungsvermögen","Veröffentlichen benutzerdefinierter Fähigkeiten, um sie mit der AI-Agenten-Community zu teilen"],"pt":["Descobrir e instalar novas habilidades do Índice da Skild","Gerenciar e atualizar habilidades existentes para desempenho ótimo","Publicar habilidades personalizadas para compartilhar com a comunidade de agentes de IA"],"ru":["Обнаружение и установка новых навыков из Индекса Skild","Управление и обновление существующих навыков для оптимальной производительности","Публикация пользовательских навыков для обмена с сообществом агентов ИИ"],"ar":["اكتشاف وتثبيت مهارات جديدة من فهرس Skild","إدارة وتحديث المهارات الحالية لتحقيق أداء مثالي","نشر مهارات مخصصة لمشاركتها مع مجتمع وكلاء الاستخبارات الاصطناعية"]},"limitations":{"en":["Requires access to the Skild registry and API","Dependent on the availability of skills within the Skild Index"],"zh":["需要访问Skild注册表和API","依赖于Skild索引中的技能的可用性"],"ja":["SkildレジストリとAPIへのアクセスが必要","Skildインデックス内のスキルの可用性に依存する"],"ko":["Skild 등록표 및 API에 대한 액세스가 필요함","Skild 색인 내의 스킬의 가용성에 의존함"],"es":["Requiere acceso al registro y la API de Skild","Depende de la disponibilidad de habilidades dentro del índice de Skild"],"fr":["Nécessite un accès au registre et à l''API Skild","Dépend de la disponibilité des compétences au sein de l''Index Skild"],"de":["Benötigt Zugriff auf das Skild-Register und die Skild-API","Hängt von der Verfügbarkeit von Fähigkeiten innerhalb des Skild-Index ab"],"pt":["Requer acesso ao registro e à API da Skild","Dependente da disponibilidade de habilidades dentro do Índice da Skild"],"ru":["Требует доступа к реестру и API Skild","Зависит от наличия навыков внутри Индекса Skild"],"ar":["يتطلب الوصول إلى السجل و API Skild","يعتمد على توافر المهارات داخل فهرس Skild"]},"version":3},"contentHash":"1a646f1a3ea62ad7724b4cf478e9ceb91c10bb91973002c887f43ab4c7111e3f","qualityScore":75}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kasperjunge/agent-resources/create-plan', 'community', 'kasperjunge', 'agent-resources', 'kasperjunge/agent-resources', 'create-plan', 0, 0, 70, '2026-02-20T04:13:19.578Z', '2026-02-20T04:54:42.998Z', 'f17076f83982f3dc4f1c50870101bde71811920121acbe5301a50f928c93d05c', '{"id":"kasperjunge/agent-resources/create-plan","name":"create-plan","description":{"zh":"创建计划是一个 AI 代理技能包管理器，允许您从 GitHub 安装技能并创建实施计划","ja":"プランの作成は、AI エージェントスキルパッケージマネージャーであり、GitHub からスキルをインストールして実装計画を作成できる","ko":"계획 생성은 AI 에이전트 스킬 패키지 관리자로서 GitHub에서 스킬을 설치하고 구현 계획을 생성할 수 있는 기능입니다","es":"La herramienta create-plan te permite crear un plan de implementación completo y entrar en modo de planificación para la ejecución del proyecto","fr":"L''outil create-plan vous permet de créer un plan d''implémentation complet et d''entrer en mode de planification pour l''exécution du projet","de":"Das Tool create-plan ermöglicht es Ihnen, einen umfassenden Implementierungsplan zu erstellen und in den Planungsmodus für die Ausführung des Projekts zu wechseln","pt":"Create-Plan é um gerenciador de pacotes para agentes de IA que permite criar planos de implementação abrangentes.","ru":"Create-Plan — менеджер пакетов для агентов ИИ, который позволяет создавать комплексные планы реализации.","ar":"Create-Plan هو مدير حزم لعمليات الذكاء الاصطناعي الذي يسمح بإنشاء خطط تنفيذ شاملة.","en":"A package manager for AI agents. Install agent skills from GitHub with a single command."},"seo":{"title":{"zh":"创建计划 - AI 代理技能包管理","ja":"プランの作成 - AI エージェントスキルパッケージマネージャー","ko":"계획 생성 - AI 에이전트 스킬 패키지 관리자","es":"Crea un plan de implementación efectivo","fr":"Créez un plan d''implémentation complet","de":"Erstellen Sie einen umfassenden Implementierungsplan","pt":"Crie Planos de Implementação com Create-Plan","ru":"Создайте план реализации с Create-Plan","ar":"أنشئ خطط التنفيذ مع Create-Plan","en":"create-plan"},"description":{"zh":"创建计划是一个 AI 代理技能包管理器，允许您从 GitHub 安装技能并创建实施计划","ja":"プランの作成は、AI エージェントスキルパッケージマネージャーであり、GitHub からスキルをインストールして実装計画を作成できる","ko":"계획 생성은 AI 에이전트 스킬 패키지 관리자로서 GitHub에서 스킬을 설치하고 구현 계획을 생성할 수 있는 기능입니다","es":"La herramienta create-plan te permite crear un plan de implementación completo y entrar en modo de planificación para la ejecución del proyecto","fr":"L''outil create-plan vous permet de créer un plan d''implémentation complet et d''entrer en mode de planification pour l''exécution du projet","de":"Das Tool create-plan ermöglicht es Ihnen, einen umfassenden Implementierungsplan zu erstellen und in den Planungsmodus für die Ausführung des Projekts zu wec...","pt":"Create-Plan é um gerenciador de pacotes para agentes de IA que permite criar planos de implementação abrangentes.","ru":"Create-Plan — менеджер пакетов для агентов ИИ, который позволяет создавать комплексные планы реализации.","ar":"Create-Plan هو مدير حزم لعمليات الذكاء الاصطناعي الذي يسمح بإنشاء خطط تنفيذ شاملة.","en":"A package manager for AI agents. Install agent skills from GitHub with a single command."},"definition":{"en":"A package manager for AI agents. Install agent skills from GitHub with a single command."},"features":{"zh":["从 GitHub 安装 AI 代理技能","创建全面实施计划","支持单一命令安装","简化 AI 代理技能管理","提高开发效率"],"ja":["GitHub から AI エージェントスキルをインストール","包括的な実装計画を作成","1 つのコマンドでインストール","AI エージェントスキルの管理を簡素化","開発効率を向上"],"ko":["GitHub에서 AI 에이전트 스킬 설치","포괄적인 구현 계획 생성","하나의 명령으로 설치","AI 에이전트 스킬 관리를 단순화","개발 효율성을 향상"],"es":["Creación de un plan de implementación completo","Gestión de paquetes para agentes de IA","Instalación de habilidades de agente desde GitHub","Modo de planificación para la ejecución del proyecto","Integración con el flujo de trabajo de desarrollo"],"fr":["Création d''un plan d''implémentation complet","Gestion de paquets pour les agents de l''IA","Installation de capacités d''agent depuis GitHub","Mode de planification pour l''exécution du projet","Intégration avec le flux de travail de développement"],"de":["Erstellung eines umfassenden Implementierungsplans","Paketmanagement für KI-Agenten","Installation von Agentenfähigkeiten von GitHub","Planungsmodus für die Ausführung des Projekts","Integration in den Entwicklungsworkflow"],"pt":["Criação de planos de implementação abrangentes","Instalação de habilidades de agente de IA do GitHub","Modo de plano para execução","Integração com fluxo de trabalho de desenvolvimento","Princípios de primeira ordem e simplicidade"],"ru":["Создание комплексных планов реализации","Установка навыков агента ИИ из GitHub","Режим плана для выполнения","Интеграция с рабочим процессом разработки","Принципы первого порядка и простоты"],"ar":["إنشاء خطط تنفيذ شاملة","تثبيت مهارات عمليات الذكاء الاصطناعي من GitHub","وضع الخطة للتنفيذ","التكامل مع تدفق العمل التطويري","مبادئ من الدرجة الأولى والبساطة"]},"keywords":{"zh":["AI 代理技能包管理","创建计划","GitHub 安装","AI 代理技能","开发效率","实施计划"],"ja":["AI エージェントスキルパッケージマネージャー","プランの作成","GitHub インストール","AI エージェントスキル","開発効率","実装計画"],"ko":["AI 에이전트 스킬 패키지 관리자","계획 생성","GitHub 설치","AI 에이전트 스킬","개발 효율성","구현 계획"],"es":["plan de implementación","desarrollo de software","agentes de IA","gestión de paquetes","GitHub","flujo de trabajo de desarrollo"],"fr":["plan d''implémentation","développement de logiciels","agents de l''IA","gestion de paquets","GitHub","flux de travail de développement"],"de":["Implementierungsplan","Softwareentwicklung","KI-Agenten","Paketmanagement","GitHub","Entwicklungsworkflow"],"pt":["Create-Plan","gerenciador de pacotes","agentes de IA","plano de implementação","desenvolvimento de software","fluxo de trabalho","princípios de primeira ordem"],"ru":["Create-Plan","менеджер пакетов","агенты ИИ","план реализации","разработка программного обеспечения","рабочий процесс","принципы первого порядка"],"ar":["Create-Plan","مدير الحزم","عمليات الذكاء الاصطناعي","خطة التنفيذ","تطوير البرمجيات","تدفق العمل","مبادئ من الدرجة الأولى"]}},"owner":"kasperjunge","repo":"agent-resources","repoPath":"kasperjunge/agent-resources","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"create-plan","description":"Use when solution space exploration is complete and youre ready to create an implementation plan. Enforces simple over easy - the fundamentally right solution, not the path of least resistance. Triggers after /design-solution, when a solution has been chosen, or when asked to make a plan or create a plan.","bodyPreview":"# Create Plan\n\nCreate a comprehensive implementation plan and enter plan mode for execution.\n\n## Position in Workflow\n\nStep 4 of development workflow:\n1. `/research` - Understand problem, explore implementation\n2. `/brainstorm-solutions` - Explore solutions\n3. `/design-solution` - Converge on a solution\n4. `/make-plan` - Create implementation plan (THIS)\n5. Code, review, ship\n\n## Core Principle\n\n**First principles. Simple over easy. Go deep.**\n\nYou have a bias toward finishing quickly. Resist it","body":"# Create Plan\n\nCreate a comprehensive implementation plan and enter plan mode for execution.\n\n## Position in Workflow\n\nStep 4 of development workflow:\n1. `/research` - Understand problem, explore implementation\n2. `/brainstorm-solutions` - Explore solutions\n3. `/design-solution` - Converge on a solution\n4. `/make-plan` - Create implementation plan (THIS)\n5. Code, review, ship\n\n## Core Principle\n\n**First principles. Simple over easy. Go deep.**\n\nYou have a bias toward finishing quickly. Resist it.\n\nNever cut corners or take the path of least resistance. Prefer the fundamentally right solution even if it requires significantly more work. The cost of a suboptimal solution compounds over time. Rushed plans degrade codebases.\n\n**Simple ≠ Easy:**\n- **Easy**: Less work now, more pain later (shortcuts, hacks, \"good enough\")\n- **Simple**: More work now, less pain forever (clean, maintainable, right)\n\nAlways choose simple. Always go deep enough to find it.\n\n## Input\n\n**Default:** Use chosen solution from current conversation context.\n\n**If argument provided:** Additional constraint or clarification for the plan.\n\n## Workflow\n\n### 1. Verify Ready State\n\nBefore planning, confirm:\n- Research is complete (problem understood)\n- Solution space was explored\n- A solution has been chosen\n\nIf missing context, ask: \"I need [research/solution choice] before creating a plan. Should I run `/research` or `/design-solution` first?\"\n\n### 2. Specify Behavior Explicitly\n\n**This is the most critical step.** Be exhaustive.\n\nFor each feature/change, document:\n\n#### Desired Behavior\n- What SHOULD happen in normal cases\n- Expected outputs for typical inputs\n- Success criteria\n\n#### Undesired Behavior\n- What MUST NOT happen\n- Edge cases to handle gracefully\n- Error conditions and their responses\n\n#### Usage Patterns\n- Common usage patterns (happy path)\n- Unhappy paths (errors, edge cases, invalid input)\n- Boundary conditions\n\n**Example format:**\n```\n## Behavior: User Authentication\n\n### Desired\n- Valid credentials → session created, redirect to dashboard\n- Session expires after 24h of inactivity\n- Invalid credentials → clear error message, no session\n\n### Undesired\n- NEVER store password in plain text\n- NEVER expose session token in URL\n- NEVER allow infinite login attempts\n\n### Edge Cases\n- Expired password → prompt reset before login\n- Concurrent sessions → configurable limit\n- Network timeout during auth → retry with backoff\n```\n\n### 3. Go Deep - Gather Sufficient Context\n\n**Do not plan without full understanding.** Read more code than feels necessary. Understand the implications of each decision.\n\nBefore finalizing any part of the plan:\n- Read all related files, not just the obvious ones\n- Understand how similar problems were solved elsewhere in the codebase\n- Trace the full impact of proposed changes\n- Identify hidden dependencies and side effects\n\n**You are not ready to plan if:**\n- You haven''t read the files your changes will affect\n- You don''t understand the existing patterns in this area\n- You''re making assumptions instead of verifying\n\n### 4. Apply First Principles Check\n\nFor each part of the plan, challenge ruthlessly:\n\n| Question | Purpose |\n|----------|---------|\n| Is this necessary? | Avoid bloat |\n| Is there a simpler approach? | Simple > easy |\n| Does this fight the codebase? | Respect existing patterns |\n| What would we regret in 6 months? | Long-term thinking |\n| Are we cutting corners? | No shortcuts |\n| Do I have enough context? | Go deeper if uncertain |\n\n**Red flags - STOP and reconsider:**\n- \"This is faster but...\" → You''re choosing easy over simple\n- \"We can clean this up later...\" → You won''t. Do it right now.\n- \"Good enough for now...\" → It will become permanent tech debt\n- Adding TODO comments for \"later\" → Later never comes\n- Skipping error handling \"for simplicity\" → That''s not simplicity, it''s negligence\n- \"I think this should work...\" → You don''t know. Go read more code.\n- Feeling rushed → Slow down. Bad plans cost more than slow plans.\n\n### 5. Design Tests\n\nWrite test specifications BEFORE implementation details:\n\n**Test design principles:**\n- Test behavior, not implementation\n- Cover happy paths AND edge cases\n- One assertion per test (when practical)\n- Tests should be fast and isolated\n\n**Format:**\n```\n## Tests\n\n### Unit Tests\n- `test_valid_credentials_creates_session` - happy path\n- `test_invalid_credentials_returns_error` - error case\n- `test_expired_password_prompts_reset` - edge case\n\n### Integration Tests\n- `test_full_login_flow_with_redirect`\n- `test_session_timeout_behavior`\n```\n\n### 6. Enter Plan Mode\n\nAfter documenting behavior and tests, switch to plan mode:\n\n**Say:** \"Entering plan mode to create the implementation plan.\"\n\nThen use the `EnterPlanMode` tool.\n\n## Output Format (Before Plan Mode)\n\n```markdown\n## Implementation Plan: [Feature Name]\n\n### Chosen Solution\n[Brief restatement of chosen approach from /design-solution]\n\n### Behavior Specification\n\n#### [Component/Feature 1]\n\n**Desired:**\n- [What should happen]\n\n**Undesired:**\n- [What must not happen]\n\n**Edge Cases:**\n- [Boundary conditions and handling]\n\n#### [Component/Feature 2]\n[Same structure]\n\n### Tests\n\n#### Unit Tests\n- `test_name` - [what it verifies]\n\n#### Integration Tests\n- `test_name` - [what it verifies]\n\n### First Principles Check\n- [Confirmation that no shortcuts are taken]\n- [Confirmation of simplest viable approach]\n- [Alignment with existing patterns]\n\n---\n\nEntering plan mode to create implementation steps.\n```\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Insufficient context gathering | Read ALL related files before planning |\n| Vague behavior specs | Write explicit examples for each case |\n| Only happy path | Always include unhappy paths and edge cases |\n| Tests as afterthought | Design tests BEFORE implementation |\n| Shortcut rationalization | Apply first principles check ruthlessly |\n| Rushing to plan mode | Complete behavior spec first |\n| Missing \"undesired\" section | Explicitly state what must NOT happen |\n| Planning with assumptions | Verify by reading code, don''t assume |\n| Choosing easy over simple | More work now = less pain forever |\n\n## What NOT to Do\n\n- Do NOT plan without reading all affected code\n- Do NOT make assumptions - verify by reading\n- Do NOT skip behavior specification\n- Do NOT leave edge cases undefined\n- Do NOT take shortcuts for \"simplicity\"\n- Do NOT skip the first principles check\n- Do NOT enter plan mode without tests designed\n- Do NOT proceed if solution wasn''t explicitly chosen\n- Do NOT rush - bad plans cost more than slow plans\n- Do NOT rationalize shortcuts with \"we can fix it later\"\n"},"lastSynced":"2026-02-20T04:54:42.998Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined project planning and execution capabilities.","zh":"非常适合需要简化项目规划和执行能力的开发代理。","ja":"開発エージェントがプロジェクト計画と実施をストリームライン化する必要がある場合に最適です。","ko":"프로젝트 계획 및 실행 능력을 간소화해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan capacidades de planificación y ejecución de proyectos optimizadas.","fr":"Parfait pour les agents de développement ayant besoin de capacités de planification et d''exécution de projets rationalisées.","de":"Perfekt für Entwicklungsmittel, die optimierte Projektplanungs- und -ausführungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de capacidades de planejamento e execução de projetos otimizados.","ru":"Идеально подходит для агентов разработки, которым необходимы оптимизированные возможности планирования и выполнения проектов.","ar":"مثالي لعميل التطوير الذي يحتاج إلى قدرات التخطيط والتنفيذ المُستَهَلَكَة للمشاريع."},"recommendation":{"en":"Empowers agents to create comprehensive implementation plans, execute them in plan mode, and manage workflows using first principles, simple design, and deep analysis, leveraging GitHub repositories and supporting protocols like HTTP for seamless skill installation.","zh":"赋予代理创建综合实施计划、在计划模式下执行它们、并使用第一原则、简单设计和深入分析来管理工作流，利用GitHub仓库和支持HTTP等协议的无缝技能安装。","ja":"エージェントが包括的な実施計画を作成し、計画モードで実行し、第一原則、シンプルな設計、そして深い分析を使用してワークフローを管理することを可能にし、GitHubリポジトリとHTTPなどのプロトコルをサポートしてスムーズなスキルインストールを実現します。","ko":"에이전트가 포괄적인 구현 계획을 만들고, 계획 모드에서 실행하고, 제1 원리, 단순한 설계 및 심층 분석을 사용하여 워크플ロー 관리를 가능하게 하며, GitHub 리포지토리와 HTTP 등의 프로토콜을 지원하여 무화석 기술 설치를 구현합니다.","es":"Habilita a los agentes a crear planes de implementación integrales, ejecutarlos en modo de plan y gestionar flujos de trabajo utilizando principios básicos, diseño simple y análisis profundo, aprovechando los repositorios de GitHub y protocolos como HTTP para una instalación de habilidades sin problemas.","fr":"Permet aux agents de créer des plans de mise en œuvre complets, de les exécuter en mode plan et de gérer les flux de travail en utilisant les principes de base, la conception simple et l''analyse approfondie, en exploitant les référentiels GitHub et les protocoles comme HTTP pour une installation de compétences sans problème.","de":"Ermächtigt Agenten, umfassende Implementierungspläne zu erstellen, diese im Planmodus auszuführen und Workflows mithilfe von Grundprinzipien, einfacher Gestaltung und tiefer Analyse zu verwalten, indem GitHub-Repositorys und Protokolle wie HTTP für eine reibungslose Fähigkeitsinstallation genutzt werden.","pt":"Habilite os agentes a criar planos de implementação abrangentes, executá-los no modo de plano e gerenciar fluxos de trabalho usando princípios fundamentais, design simples e análise profunda, aproveitando repositórios GitHub e protocolos de suporte como HTTP para instalação de habilidades sem interrupções.","ru":"Наделяет агентов возможностью создавать комплексные планы реализации, выполнять их в режиме планирования и управлять рабочими процессами с использованием основных принципов, простого дизайна и глубокого анализа, используя репозитории GitHub и поддерживаемые протоколы, такие как HTTP, для бесшовной установки навыков.","ar":"يمكن للعاملين من خلاله إعطاء الوكلاء إمكانية إنشاء خطط تنفيذ شاملة، وتنفيذها في وضع الخطة، وإدارة تدفقات العمل باستخدام المبادئ الأساسية والتصميم البسيط والتحليل العميق، مستفيدة من مستودعات جيت هاب والبروتوكولات المدعومة مثل بروتوكول نقل النص الفعلي لتحديث المهارات بدون انقطاع."},"useCases":{"en":["Creating step-by-step development workflows","Managing GitHub-based skill installations","Executing plans in a controlled environment"],"zh":["创建分步开发工作流","管理基于GitHub的技能安装","在受控环境中执行计划"],"ja":["ステップバイステップの開発ワークフローを作成する","GitHubベースのスキルインストールを管理する","制御された環境で計画を実行する"],"ko":["단계별 개발 워크플ロー 생성","GitHub 기반 스킬 설치 관리","제어 환경에서 계획 실행"],"es":["Creación de flujos de trabajo de desarrollo paso a paso","Gestión de instalaciones de habilidades basadas en GitHub","Ejecución de planes en un entorno controlado"],"fr":["Création de flux de travail de développement étape par étape","Gestion des installations de compétences basées sur GitHub","Exécution de plans dans un environnement contrôlé"],"de":["Erstellung von schrittweisen Entwicklungswerkflüssen","Verwaltung von GitHub-basierten Fähigkeitsinstallationen","Ausführung von Plänen in einer kontrollierten Umgebung"],"pt":["Criação de fluxos de trabalho de desenvolvimento passo a passo","Gerenciamento de instalações de habilidades baseadas em GitHub","Execução de planos em um ambiente controlado"],"ru":["Создание пошаговых рабочих процессов разработки","Управление установками навыков на основе GitHub","Выполнение планов в контролируемой среде"],"ar":["إنشاء تدفقات عمل تطوير خطوة بخطوة","إدارة تثبيتات المهارات الموجودة على جيت هاب","تنفيذ الخطط في بيئة محكمة"]},"limitations":{"en":["Requires access to GitHub repositories","Dependent on agent''s understanding of first principles and simple design"],"zh":["需要访问GitHub仓库","依赖于代理对第一原则和简单设计的理解"],"ja":["GitHubリポジトリへのアクセスが必要","エージェントの第一原則とシンプルな設計の理解に依存する"],"ko":["GitHub 리포지토리에 대한 액세스가 필요함","에이전트의 제1 원리 및 단순한 설계에 대한 이해에 의존"],"es":["Requiere acceso a los repositorios de GitHub","Depende de la comprensión del agente sobre principios básicos y diseño simple"],"fr":["Nécessite un accès aux référentiels GitHub","Dépend de la compréhension de l''agent sur les principes de base et la conception simple"],"de":["Benötigt Zugriff auf GitHub-Repositorys","Hängt von dem Verständnis des Agenten über Grundprinzipien und einfache Gestaltung ab"],"pt":["Exige acesso a repositórios GitHub","Depende da compreensão do agente sobre princípios fundamentais e design simples"],"ru":["Требует доступа к репозиториям GitHub","Зависит от понимания агентом основных принципов и простого дизайна"],"ar":["يتطلب الوصول إلى مستودعات جيت هاب","يعتمد على فهم الوكيل للمبادئ الأساسية والتصميم البسيط"]},"version":3},"contentHash":"f17076f83982f3dc4f1c50870101bde71811920121acbe5301a50f928c93d05c","qualityScore":70}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AndreevED/1c-ai-feature-dev-workflow/1c-feature-dev', 'community', 'AndreevED', '1c-ai-feature-dev-workflow', 'AndreevED/1c-ai-feature-dev-workflow', '1c-feature-dev', 0, 0, 0, '2026-02-20T04:13:19.578Z', '2026-02-20T04:54:49.978Z', '5d7fd83004cb9106450b7e6a49884ef1cba676c0f5dbebe4cc5ad1fe1ea9f1d3', '{"id":"AndreevED/1c-ai-feature-dev-workflow/1c-feature-dev","name":"1c-feature-dev","description":{"zh":"1C开发工作流是一个AI驱动的开发过程，包括分析、架构、代码和审查。它能够提高开发效率和质量。","ja":"1C開発ワークフローは、分析、設計、コード、レビューを含むAI駆動の開発プロセスです。開発の効率と品質を向上させます。","ko":"1C 개발 워크플로우는 분석, 아키텍처, 코드 및 리뷰를 포함하는 AI驱动의 개발 프로세스입니다. 개발 효율성과 품질을 향상시킵니다.","es":"Nuestra solución de IA para el desarrollo de características 1C ofrece un enfoque integral para analizar, diseñar, codificar y revisar. Mejora la eficiencia y reduce errores.","fr":"Notre solution IA pour le développement de fonctionnalités 1C propose une approche globale pour analyser, concevoir, coder et revoir. Améliorez l''efficacité et réduisez les erreurs.","de":"Unsere KI-Lösung für die Entwicklung von 1C-Features bietet einen umfassenden Ansatz für die Analyse, das Design, den Code und die Überprüfung. Steigern Sie die Effizienz und reduzieren Sie Fehler.","pt":"O skill 1c-feature-dev é uma abordagem inovadora para desenvolvimento de recursos 1C, utilizando análise, arquitetura e revisão para garantir a qualidade","ru":"Скилл 1с-фичер-дев - это инновационный подход к разработке доработок 1С, использующий анализ, архитектуру и ревью для обеспечения качества","ar":"المهارة 1c-feature-dev هي وسيلة مبتكرة لتطوير ميزات 1C، تستخدم التحليل والتصميم والمراجعة لضمان الجودة","en":"AI-воркфлоу для разработки доработок 1С: анализ, архитектура, код, ревью"},"seo":{"title":{"zh":"1C开发工作流优化","ja":"1C開発ワークフロー最適化","ko":"1C 개발 워크플로우 최적화","es":"Desarrollo de características 1C con IA","fr":"Développement de fonctionnalités 1C avec IA","de":"1C-Feature-Entwicklung mit KI","pt":"Desenvolvimento de Recursos 1C com AI","ru":"1с-фичер-дев: разработка доработок с AI","ar":"تطوير ميزات 1C باستخدام الذكاء الاصطناعي","en":"1c-feature-dev"},"description":{"zh":"1C开发工作流是一个AI驱动的开发过程，包括分析、架构、代码和审查。它能够提高开发效率和质量。","ja":"1C開発ワークフローは、分析、設計、コード、レビューを含むAI駆動の開発プロセスです。開発の効率と品質を向上させます。","ko":"1C 개발 워크플로우는 분석, 아키텍처, 코드 및 리뷰를 포함하는 AI驱动의 개발 프로세스입니다. 개발 효율성과 품질을 향상시킵니다.","es":"Nuestra solución de IA para el desarrollo de características 1C ofrece un enfoque integral para analizar, diseñar, codificar y revisar. Mejora la eficiencia ...","fr":"Notre solution IA pour le développement de fonctionnalités 1C propose une approche globale pour analyser, concevoir, coder et revoir. Améliorez l''efficacité ...","de":"Unsere KI-Lösung für die Entwicklung von 1C-Features bietet einen umfassenden Ansatz für die Analyse, das Design, den Code und die Überprüfung. Steigern Sie ...","pt":"O skill 1c-feature-dev é uma abordagem inovadora para desenvolvimento de recursos 1C, utilizando análise, arquitetura e revisão para garantir a qualidade","ru":"Скилл 1с-фичер-дев - это инновационный подход к разработке доработок 1С, использующий анализ, архитектуру и ревью для обеспечения качества","ar":"المهارة 1c-feature-dev هي وسيلة مبتكرة لتطوير ميزات 1C، تستخدم التحليل والتصميم والمراجعة لضمان الجودة","en":"AI-воркфлоу для разработки доработок 1С: анализ, архитектура, код, ревью"},"definition":{"en":"AI-воркфлоу для разработки доработок 1С: анализ, архитектура, код, ревью"},"features":{"zh":["适应性开发","早期验证","需求澄清","原子化步骤","进度跟踪"],"ja":["適応性開発","早期検証","要件明確化","原子化ステップ","進度追跡"],"ko":["적응성 개발","초기 검증","요구사항 명확화","원자화 단계","진행 상황 추적"],"es":["Análisis adaptativo","Validación temprana","Clarificación de requisitos","Pasos atómicos","Seguimiento del progreso"],"fr":["Analyse adaptative","Validation précoce","Clarification des exigences","Étapes atomiques","Suivi de la progression"],"de":["Adaptiver Analyse","Frühzeitige Validierung","Anforderungsklärung","Atomare Schritte","Fortschrittsüberwachung"],"pt":["Análise adaptativa","Revisão prévia do plano","Especificações claras","Etapes atômicas de implementação","Acompanhamento de progresso"],"ru":["Адаптивный анализ","Раннее ревью плана","Ясные требования","Атомарные шаги реализации","Отслеживание прогресса"],"ar":["تحليل مرن","مراجعة مبكرة للخطة","مواصفات واضحة","خطوات تطبيق ذرية","مراقبة التقدم"]},"keywords":{"zh":["1C开发","AI工作流","开发效率","代码审查","需求分析","软件开发"],"ja":["1C開発","AIワークフロー","開発効率","コードレビュー","要件分析","ソフトウェア開発"],"ko":["1C 개발","AI 워크플로우","개발 효율성","코드 리뷰","요구사항 분석","소프트웨어 개발"],"es":["desarrollo de características 1C","IA en el desarrollo de software","análisis adaptativo","validación temprana","clarificación de requisitos","pasos atómicos","seguimiento del progreso"],"fr":["développement de fonctionnalités 1C","IA dans le développement de logiciels","analyse adaptative","validation précoce","clarification des exigences","étapes atomiques","suivi de la progression"],"de":["1C-Feature-Entwicklung","KI im Software-Entwicklungsprozess","adaptiver Analyse","frühzeitige Validierung","Anforderungsklärung","atomare Schritte","Fortschrittsüberwachung"],"pt":["desenvolvimento de recursos 1C","análise de requisitos","arquitetura de software","revisão de código","desenvolvimento ágil","inteligência artificial"],"ru":["разработка доработок 1С","анализ требований","архитектура программного обеспечения","ревью кода","гибкая разработка","искусственный интеллект"],"ar":["تطوير ميزات 1C","تحليل المتطلبات","هندسة البرمجيات","مراجعة الكود","التطوير المرن","الذكاء الاصطناعي"]}},"owner":"AndreevED","repo":"1c-ai-feature-dev-workflow","repoPath":"AndreevED/1c-ai-feature-dev-workflow","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"1c-feature-dev","description":"Этот скилл следует использовать, когда пользователь просит создать доработку 1C, реализовать функционал 1C, добавить новую возможность в 1C, разработать модуль 1C, сделать доработку в 1С или нуждается в полном цикле разработки 1C-доработок от анализа до реализации с валидацией плана и проверками приемки.","bodyPreview":"## Принципы работы\n\n- **Адаптивность**: количество агентов и глубина анализа зависят от сложности задачи\n- **Ранняя валидация**: ревью плана до реализации, а не после\n- **Уточнение требований**: выявление всех неоднозначностей до проектирования через вопросы пользователю\n- **Атомарные шаги**: этапы реализации с критериями приемки и проверками\n- **Отслеживание прогресса**: после завершения каждой фазы отмечай её как завершённую в списке задач\n\n---\n\n## Phase 0: Инициализация и оценка сложности\n\n**","body":"## Принципы работы\n\n- **Адаптивность**: количество агентов и глубина анализа зависят от сложности задачи\n- **Ранняя валидация**: ревью плана до реализации, а не после\n- **Уточнение требований**: выявление всех неоднозначностей до проектирования через вопросы пользователю\n- **Атомарные шаги**: этапы реализации с критериями приемки и проверками\n- **Отслеживание прогресса**: после завершения каждой фазы отмечай её как завершённую в списке задач\n\n---\n\n## Phase 0: Инициализация и оценка сложности\n\n**Цель**: понять масштаб задачи и создать структуру для работы\n\nНачальный запрос: $ARGUMENTS\n\n**Действия**:\n1. Создай список задач со всеми фазами\n2. Создай директорию `.tasks/task-[feature-name]/` для хранения артефактов\n3. **Оцени сложность задачи** (простая/средняя/сложная/критичная):\n   - **Простая**: небольшое изменение, очевидная реализация\n   - **Средняя**: затрагивает несколько модулей, требует понимания архитектуры\n   - **Сложная**: большая доработка, несколько подсистем, неочевидные решения\n   - **Критичная**: архитектурные изменения, влияние на всю систему, высокие риски\n4. Запиши оценку сложности в файл `.tasks/task-[feature-name]/phase0-complexity.md`\n\n---\n\n## Phase 1: Discovery\n\n**Цель**: понять, что нужно построить\n\n**Действия**:\n1. Если доработка неясна, спроси пользователя:\n   - Какую проблему они решают?\n   - Что должна делать доработка?\n   - Есть ли ограничения или требования?\n2. Резюмируй понимание и получи подтверждение от пользователя\n3. Сохрани подтвержденное понимание в файл `.tasks/task-[feature-name]/phase1-requirements.md`:\n   - Исходный запрос из $ARGUMENTS\n   - Уточняющие вопросы и ответы (если были)\n   - Резюме понимания задачи\n   - Ключевые требования и ограничения\n   - Подтверждение пользователя\n\n---\n\n## Phase 2: Исследование кодовой базы 1C\n\n**Цель**: понять существующий код и паттерны\n\n**ПРИНЦИПЫ АДАПТИВНОГО ИССЛЕДОВАНИЯ**:\n\nТЫ ПРИНИМАЕШЬ РЕШЕНИЕ о стратегии исследования на основе:\n- Оценки сложности из Phase 0\n- Характера задачи (новая доработка vs расширение существующей)\n- Того, насколько понятна область кодовой базы\n\n**Ключевой принцип**: глубина важнее ширины - лучше запустить агентов последовательно для углубления, чем параллельно на одно и то же.\n\n**Твои решения**:\n1. **Сколько агентов `1c-code-explorer` запустить?** (1-4+)\n   - Для простых задач может хватить одного\n   - Для сложных может понадобиться несколько с углублением\n\n2. **Параллельно или последовательно?**\n   - Параллельно - если нужно изучить разные независимые области\n   - Последовательно - если нужно углубление: первый агент находит, второй копает глубже\n\n3. **На какие аспекты фокусироваться?**\n   - Похожие доработки и паттерны\n   - Архитектура и слои абстракции\n   - Интеграции и зависимости\n   - Критичные компоненты, найденные предыдущими агентами\n\n4. **Итеративное углубление**\n   - Можешь запустить агента, посмотреть результаты, решить нужно ли ещё углубление\n   - Каждый следующий агент может фокусироваться на находках предыдущих\n\n**Действия**:\n1. Прими решение о стратегии исследования (обоснуй коротко)\n2. Запусти агентов `1c-code-explorer` согласно своей стратегии:\n   - Передай путь к требованиям: `phase1-requirements.md`\n   - Укажи фокус исследования для каждого агента (паттерны, архитектура, похожие доработки и т.д.)\n3. Каждый агент должен вернуть список нескольких ключевых файлов для чтения\n4. Прочитай все указанные файлы для глубокого понимания\n5. Оцени: достаточно ли понимания? Нужно ли ещё углубление? Если да - запусти ещё агентов\n6. Представь полную сводку найденных паттернов\n7. Сохрани сводку в файл `.tasks/task-[feature-name]/phase2-exploration.md`:\n   - Найденные паттерны и соглашения\n   - Похожие доработки с ссылками на файлы\n   - Ключевые компоненты и их назначение\n   - Архитектурные инсайты\n   - Список всех прочитанных ключевых файлов\n\n---\n\n## Phase 3: Уточняющие вопросы\n\n**Цель**: заполнить пробелы и разрешить все неоднозначности ДО проектирования\n\n**Действия**:\n1. Просмотри находки по кодовой базе и исходный запрос на доработку\n2. Выяви недетализированные аспекты: граничные случаи, обработка ошибок, точки интеграции, границы области, предпочтения дизайна, обратная совместимость, потребности производительности\n3. **Представь все вопросы пользователю в ясном, организованном списке**\n4. **Жди ответов перед проектированием архитектуры**\n5. Сохрани вопросы и ответы в файл `.tasks/task-[feature-name]/phase3-clarifications.md`:\n   - Список вопросов с контекстом\n   - Ответы пользователя на каждый вопрос\n   - Принятые решения и рекомендации\n\nЕсли пользователь говорит \"как считаешь нужным\", предоставь свою рекомендацию и получи явное подтверждение.\n\n---\n\n## Phase 4: Проектирование архитектуры\n\n**Цель**: спроектировать архитектуру реализации\n\n**АДАПТИВНЫЙ ПОДХОД** - количество агентов зависит от сложности:\n\n### Простая задача (1 агент):\n- Запусти 1 агента `1c-code-architect`\n- Создай один практичный план реализации\n\n### Средняя задача (1 агент + опциональное мультисэмплинг):\n- **По умолчанию**: 1 агент с практичным планом\n- **Опционально**: если решение неочевидно, можешь запустить 2 агента с разными подходами и выбрать лучший\n\n### Сложная/критичная задача (2-3 агента, мультисэмплинг):\n- Запусти 2-3 агента `1c-code-architect` параллельно с разным фокусом:\n  - Минимальные изменения (наименьшее изменение, максимальное переиспользование)\n  - Чистая архитектура (поддерживаемость, элегантные абстракции)\n  - Прагматичный баланс (скорость + качество)\n- Сформируй мнение о лучшем подходе\n- Представь пользователю все подходы с твоей рекомендацией\n- **Спроси пользователя, какой подход он предпочитает**\n\n**Действия**:\n1. Запусти агентов `1c-code-architect` согласно сложности задачи:\n   - Передай пути к артефактам: `phase1-requirements.md`, `phase2-exploration.md`, `phase3-clarifications.md`\n   - Для каждого агента укажи архитектурный подход (минимальные изменения / чистая архитектура / баланс)\n2. После выбора подхода создай файл `.tasks/task-[feature-name]/phase4-architecture.md` с:\n   - Постановкой задачи\n   - Оценкой сложности из Phase 0\n   - Выбранным архитектурным подходом с обоснованием\n   - Найденными паттернами и соглашениями из Phase 2\n   - Ответами на уточняющие вопросы из Phase 3\n   - **ЭТАПАМИ РЕАЛИЗАЦИИ** - разбей реализацию на логические этапы (чеклист в markdown):\n     - **Гранулярность**: простая задача = 1 этап, средняя = 2-4, сложная = 4-8, критичная = 5-10+ (отталкивайся от атомарности)\n     - **Атомарность**: этап завершается за 1 сессию агента, имеет проверяемый результат, не блокирует сам себя\n     - **Формат**: `- [ ] **Этап N**: описание + файлы + критерии приемки + зависимости (если есть)`\n   - Mermaid-диаграммами (архитектура, потоки данных)\n   - План должен быть самодостаточным для понимания без контекста беседы\n\n---\n\n## Phase 5: Ревью плана\n\n**Цель**: валидировать план ДО реализации — ошибки в плане обходятся дорого, весь код придётся переписывать.\n\n**Действия**:\n1. Запусти агента `1c-code-architect` для ревью плана:\n   - Передай пути к артефактам: `phase1-requirements.md`, `phase2-exploration.md`, `phase3-clarifications.md`, `phase4-architecture.md`\n   - Фокус ревью:\n     - **Полнота**: все ли аспекты задачи покрыты?\n     - **Корректность**: соответствуют ли решения найденным паттернам из Phase 2?\n     - **Реалистичность**: можно ли реализовать план как описано?\n     - **Соответствие требованиям**: покрывает ли план все требования из Phase 1 и ответы из Phase 3?\n     - **Критерии приемки этапов**: достаточно ли чёткие и проверяемые?\n     - **Зависимости**: правильно ли выстроена последовательность этапов?\n     - **Технический долг**: есть ли известные проблемы, которые план усугубит?\n2. Если агент находит проблемы:\n   - Обнови план в `.tasks/task-[feature-name]/phase4-architecture.md`\n   - **Повтори Phase 5** (ревью обновлённого плана)\n3. Когда план одобрен агентом, сохрани результаты ревью в `.tasks/task-[feature-name]/phase5-plan-review.md`:\n   - Что было проверено (полнота, корректность, реалистичность и т.д.)\n   - Какие проблемы были найдены и исправлены (если были)\n   - Итоговое заключение: план готов к реализации\n4. **Представь план пользователю**:\n   - Краткое резюме плана\n   - Этапы реализации с критериями приемки\n   - **Спроси явно: \"План готов к реализации, можем начинать?\"**\n\n**НЕ ПЕРЕХОДИ К PHASE 6 БЕЗ ЯВНОГО ОДОБРЕНИЯ ПОЛЬЗОВАТЕЛЯ**\n\n---\n\n## Phase 6: Реализация по этапам\n\n**Цель**: построить доработку атомарными шагами с проверками приемки\n\n**НЕ НАЧИНАЙ БЕЗ ОДОБРЕНИЯ ПОЛЬЗОВАТЕЛЯ**\n\n**Действия**:\n1. Прочитай файл плана `.tasks/task-[feature-name]/phase4-architecture.md`\n2. **Для каждого этапа реализации последовательно**:\n   a. Отметь этап в плане как начатый (измени `- [ ]` на `- [🔄]` в файле плана)\n   b. Запусти агента `1c-code-writer` для реализации этапа:\n      - Передай путь к плану\n      - Укажи конкретный этап для реализации\n      - Напомни про критерии приемки\n   c. Проверь критерии приемки этапа:\n      - Все файлы созданы/изменены как описано?\n      - Критерии приемки выполнены?\n      - Код соответствует правилам из `1c-rules.md`?\n   d. Если критерии не выполнены:\n      - Запусти агента `1c-code-writer` для исправления:\n        - Передай путь к плану и укажи этап\n        - Опиши найденные проблемы и что нужно исправить\n      - Повтори проверку критериев\n      - Повторяй цикл исправления, пока критерии приемки не будут выполнены\n   e. Отметь этап в плане как завершённый (измени `- [🔄]` на `- [x]` в файле плана)\n\n---\n\n## Phase 7: Ревью кода\n\n**Цель**: убедиться, что код корректен, элегантен и **соответствует плану**\n\n**Действия**:\n1. Запусти ревьюеров согласно размеру задачи:\n   - **Простая**: `1c-code-reviewer`\n     - Передай путь к плану: `phase4-architecture.md`\n     - Фокус: базовая корректность + беглая проверка соответствия плану\n   - **Средняя/сложная**:\n     - `1c-code-architect` для проверки соответствия плану:\n       - Передай пути к артефактам: `phase1-requirements.md`, `phase4-architecture.md`, `phase5-plan-review.md`\n       - Фокус: соответствие плану, архитектурным решениям, критериям приемки этапов\n     - `1c-code-reviewer` для проверки качества кода:\n       - Укажи путь к правилам: `~/.claude/rules/1c-rules.md`\n       - Фокус: баги, читаемость, правила, DRY, элегантность\n   - **Очень большая**: раздели код на логические модули/подсистемы, для каждого модуля запусти пару агентов (architect + reviewer) с теми же инструкциями\n2. Консолидируй их ответы и выяви проблемы, требующие исправлений\n3. Сохрани результаты ревью в `.tasks/task-[feature-name]/phase7-code-review.md`:\n   - Что было проверено (соответствие плану, качество, баги и т.д.)\n   - Найденные проблемы с severity и рекомендациями\n   - Итоговая оценка готовности кода\n4. **Представь выявленные проблемы пользователю и спроси, что он хочет сделать**:\n   - Исправить сейчас\n   - Исправить позже (добавить в TODO/технический долг)\n   - Продолжить как есть\n5. **Если \"исправить сейчас\"**:\n   - Добавь проблемы в план в секцию \"Исправления после ревью\"\n   - Запусти агента `1c-code-writer` для исправления:\n     - Передай путь к плану: `phase4-architecture.md`\n     - Опиши проблемы из ревью и что нужно исправить\n   - **Вернись к началу Phase 7** (повторное ревью)\n   - Повторяй итерации, пока ревьюеры не перестанут находить критические проблемы\n6. **Если \"исправить позже\"**:\n   - Добавь проблемы в план в секцию \"Технический долг\"\n   - Отметь в плане как отложенные\n\n---\n\n## Phase 8: Итоги\n\n**Цель**: документировать выполненное\n\n**Действия**:\n1. Отметь все задачи как завершённые\n2. Сохрани резюме в файл `.tasks/task-[feature-name]/phase8-summary.md`:\n   - Что было построено (ссылки на этапы реализации)\n   - Ключевые принятые решения (ссылка на план)\n   - Изменённые файлы (git diff --stat)\n   - Оставшийся технический долг (если есть)\n   - Предлагаемые следующие шаги\n3. Представь резюме пользователю\n\n"},"lastSynced":"2026-02-20T04:54:49.978Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review.","zh":"适用于专门从事1C:Enterprise平台的开发代理，需要结构化的工作流管理以进行功能开发和审查。","ja":"1C:Enterpriseプラットフォームを専門とする開発エージェントに適しています。機能開発とレビューに構造化されたワークフローの管理が必要です。","ko":"1C:Enterprise 플랫폼을 전문으로 하는 개발 에이전트에게 적합합니다. 기능 개발 및 리뷰를 위한 구조화된 워크플로 관리가 필요합니다.","es":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review.","fr":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review.","de":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review.","pt":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review.","ru":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review.","ar":"Ideal for Development Agents specializing in 1C:Enterprise platform, requiring structured workflow management for feature development and review."},"recommendation":{"en":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes.","zh":"使代理能够通过自适应分析、早期验证和原子化实现步骤来管理复杂的1C功能开发，利用早期验证和需求明确等原则来确保高质量的结果。","ja":"エージェントが複雑な1C機能開発を適応分析、初期検証、原子的な実装ステップを通じて管理できるようにし、早期検証や要件の明確化などの原則を利用して、高品質の成果物を保証します。","ko":"에이전트가 적응형 분석, 초기 검증 및 원자적 구현 단계를 통해 복잡한 1C 기능 개발을 관리할 수 있도록 하며, 초기 검증 및 요구 사항 명확화 등의 원칙을 사용하여 고품질 결과를 보장합니다.","es":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes.","fr":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes.","de":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes.","pt":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes.","ru":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes.","ar":"Empowers agents to manage complex 1C feature development through adaptive analysis, early validation, and atomic implementation steps, utilizing principles like ранняя валидация and уточнение требований to ensure high-quality outcomes."},"useCases":{"en":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"],"zh":["使用自适应性和深度分析来自动化1C功能开发工作流","简化1C代码实现的审查流程","为1C功能开发生成详细的项目计划，具有原子化步骤"],"ja":["適応性と深度分析を用いて1C機能開発ワークフローを自動化する","1Cコード実装のレビュー処理を簡素化する","1C機能開発の詳細なプロジェクト計画を生成する、原子的なステップを含む"],"ko":["적응성과 심도 분석을 사용하여 1C 기능 개발 워크플로를 자동화하는 것","1C 코드 구현의 리뷰 처리를 간소화하는 것","1C 기능 개발을 위한詳細한 프로젝트 계획을 생성하는 것, 원자적 단계를 포함"],"es":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"],"fr":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"],"de":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"],"pt":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"],"ru":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"],"ar":["Automating 1C feature development workflows with адаптивность and глубина анализа","Streamlining ревью processes for 1C code implementations","Generating detailed проект плана for 1C feature development with атомарные шаги"]},"limitations":{"en":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"],"zh":["需要了解1C:Enterprise平台的具体特点","依赖于任务的复杂性来实现自适应性和深度分析"],"ja":["1C:Enterpriseプラットフォームの特性を理解する必要がある","タスクの複雑性に依存して適応性と深度分析を実現する"],"ko":["1C:Enterprise 플랫폼의 특성에 대한 이해가 필요","작업의 복잡성에 따라 적응성 및 심도 분석을 구현"],"es":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"],"fr":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"],"de":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"],"pt":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"],"ru":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"],"ar":["Requires understanding of 1C:Enterprise platform specifics","Dependent on complexity of task for адаптивность and глубина анализа"]},"version":3},"contentHash":"5d7fd83004cb9106450b7e6a49884ef1cba676c0f5dbebe4cc5ad1fe1ea9f1d3","qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rmyndharis/antigravity-skills/prompt-engineer', 'community', 'rmyndharis', 'antigravity-skills', 'rmyndharis/antigravity-skills', 'prompt-engineer', 0, 0, 80, '2026-02-20T04:13:19.578Z', '2026-02-20T04:55:26.940Z', 'd4e4e7ba871b10b8bb68f303d0e76c3bd754ec52721b7aab1c6585658afff1b1', '{"id":"rmyndharis/antigravity-skills/prompt-engineer","name":"prompt-engineer","description":{"zh":"prompt-engineer 技术技能是 Google Antigravity 的一套专业技术，提供最佳实践和工作流指导","ja":"プロンプトエンジニア専門技術は、Google Antigravity のワークフローとベストプラクティスを提供する技術スキルです","ko":"prompt-engineer 기술 스킬은 Google Antigravity의 워크플로우와베스트 프랙티스를 제공하는 기술 스킬입니다","es":"El skill de ingeniero de prompts es una colección curada de habilidades del agente para Google Antigravity, diseñada para mejorar tus tareas y flujos de trabajo","fr":"Le skill d''ingénieur de prompts est une collection soignée de compétences de l''agent pour Google Antigravity, conçue pour améliorer vos tâches et flux de travail","de":"Das Prompt-Ingenieur-Skill ist eine kuratierte Sammlung von Agent-Fähigkeiten für Google Antigravity, entwickelt um Ihre Aufgaben und Arbeitsabläufe zu verbessern","pt":"O skill de engenheiro de prompt é uma coleção curada de habilidades do agente para Google Antigravity, ajudando no desenvolvimento de tarefas e workflows","ru":"Навык инженера промпта - это отобранная коллекция навыков агента для Google Antigravity, помогающая в разработке задач и рабочих процессов","ar":"مهارة مهندس البرمجة هي مجموعة مهارات معدة مسبقاً لبرنامج جوجل أنتي جرافيتي، تساعد في تطوير المهام وسير العمل","en":"A curated collection of Agent Skills for Google Antigravity"},"seo":{"title":{"zh":"prompt-engineer 技术技能","ja":"プロンプトエンジニア専門技術","ko":"prompt-engineer 기술 스킬","es":"Ingeniero de Prompts: Guía Técnica","fr":"Ingénieur de Prompts: Guide Technique","de":"Prompt-Ingenieur: Technische Anleitung","pt":"Enge